static void match_overlay(const Dom*ram,const char*root){char p[PATH_MAX];glob_t x={0};snprintf(p,sizeof p,"%s/LEVEL*/LEVEL*.BIN",root);if(glob(p,0,NULL,&x))return;uint32_t o=0x800b0000u&0x1fffff,frag=(0x800b0180u&0x1fffff);printf("runtime_b0180=");for(unsigned j=0;j<48;j++)printf("%02x",ram->p[frag+j]);putchar('\n');for(size_t i=0;i<x.gl_pathc;i++){size_t n;uint8_t*b=slurp(x.gl_pathv[i],&n);size_t bad=0;if(o+n<=ram->n)for(size_t j=0;j<n;j++)bad+=ram->p[o+j]!=b[j];if(bad==0)printf("overlay_match file=%s bytes=%zu\n",x.gl_pathv[i],n);for(size_t at=0;at+48<=n;at++)if(!memcmp(b+at,ram->p+frag,48))printf("overlay_fragment file=%s file_offset=0x%zx\n",x.gl_pathv[i],at);free(b);}globfree(&x);}
